337	static int pan_l2cap_recv(struct bt_l2cap_chan *chan, struct net_buf *buf)
338	{
339	  uint8_t  frame[PW_PAN_FRAME_MAX];
340	  uint32_t total;
341	  uint32_t off = 0;
342	  struct net_buf *f;
343	
344	  (void)chan;
345	
346	  total = net_buf_frags_len(buf);               /* [已核实] net_buf.h:2711 static inline size_t */
347	  if (total > sizeof(frame))
348	    {
349	      g_pan.rx_drop++;
350	      net_buf_unref(buf);
351	      return 0;
352	    }
353	
354	  /* 逐片拷贝：收到的 PDU 各片 data 都指向本片载荷起点 */
355	
356	  for (f = buf; f != NULL && off < total; f = f->frags)
357	    {
358	      uint32_t n = f->len;
359	      if (n > total - off)
360	        {
361	          n = total - off;
362	        }
363	
364	      memcpy(&frame[off], f->data, n);
365	      off += n;
366	    }
367	
368	  net_buf_unref(buf);
369	
370	  if (off != total)
371	    {
372	      g_pan.rx_drop++;
373	      return 0;
374	    }
375	
376	  return pan_on_frame(frame, total);
377	}
