469	/* ---------------------------------------------------------------------------
470	 * TUN → BNEP 的发送线程
471	 * ------------------------------------------------------------------------- */
472	
473	static void *pan_tun_thread(void *arg)
474	{
475	  uint8_t eth[PW_PAN_FRAME_MAX];
476	  uint8_t wire[PW_PAN_FRAME_MAX + 8];
477	
478	  (void)arg;
479	  printf("[pan] tun thread start\n");
480	
481	  while (g_pan.thread_run)
482	    {
483	      struct pollfd pfd;
484	      int           ret;
485	      ssize_t       n;
486	
487	      pfd.fd      = g_pan.tunfd;
488	      pfd.events  = POLLIN;
489	      pfd.revents = 0;
490	
491	      ret = poll(&pfd, 1, 500);
492	      if (ret <= 0)
493	        {
494	          continue;
495	        }
496	
497	      n = read(g_pan.tunfd, eth, sizeof(eth));
498	      if (n <= 0)
499	        {
500	          continue;
501	        }
502	
503	      if (g_pan.state != PW_PAN_UP)
504	        {
505	          /* 还没握手完，帧先丢（对端这时也不会发东西给我们） */
506	          continue;
507	        }
508	
509	      {
510	        int32_t m = pw_bnep_build_data(wire, sizeof(wire), eth, (uint32_t)n);
511	        if (m > 0 && pan_send_raw(wire, (uint32_t)m) == 0)
512	          {
513	            g_pan.tx_frames++;
514	          }
515	      }
516	    }
517	
518	  printf("[pan] tun thread exit\n");
519	  return NULL;
520	}
