566	int pw_pan_start(const char *peer_mac)
567	{
568	  bt_addr_t addr;
569	  int       err;
570	
571	  if (peer_mac == NULL)
572	    {
573	      return -EINVAL;
574	    }
575	
576	  if (g_pan.state != PW_PAN_IDLE && g_pan.state != PW_PAN_FAIL)
577	    {
578	      printf("[pan] already %s\n", pan_state_name(g_pan.state));
579	      return -EBUSY;
580	    }
581	
582	  pan_reset();
583	
584	  err = bt_addr_from_str(peer_mac, &addr);      /* [已核实] addr.h:284 int (const char *, bt_addr_t *)，0 / -EINVAL */
585	  if (err != 0)
586	    {
587	      printf("[pan] bad mac '%s'\n", peer_mac);
588	      return -EINVAL;
589	    }
590	
591	  g_pan.conn = bt_conn_lookup_addr_br(&addr);   /* [已核实] conn.h:756 内联→bt_conn_lookup_addr_br_mc(0,peer)；需 CONFIG_BT_ORIGINAL_API=y；返回引用须 bt_conn_unref() */
592	  if (g_pan.conn == NULL)
593	    {
594	      /* 没有现成 ACL：提示先配对/连接。真机上可换成 bt_conn_create_br() 主动发起 */
595	      printf("[pan] no BR/EDR connection to %s (pair first)\n", peer_mac);
596	      pan_fail("no acl link");
597	      return -ENOTCONN;
598	    }
599	
600	  if (pan_tun_open() < 0)
601	    {
602	      pan_fail("tun open failed");
603	      return -EIO;
604	    }
605	
606	  g_pan.state = PW_PAN_SDP;
607	  err = bt_sdp_discover(g_pan.conn, &g_pan_sdp_params);
608	  if (err < 0)
609	    {
610	      printf("[pan] bt_sdp_discover err=%d\n", err);
611	      pan_fail("sdp discover failed");
612	      return err;
613	    }
614	
615	  pan_thread_start();
616	  return 0;
617	}
